import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`sponsorship-deck`,heroTitle:`Build your sponsorship deck in minutes`,heroSubtitle:`Perplexity Computer researches your event, sizes your audience, and builds a polished sponsorship deck with tiered packages — automatically.`,inputUrlCta:`Build my deck`,inputUrlPlaceholder:`yourevent.com`,inputUrlPrefill:`Go to {url} and do a deep analysis of this event or conference — extract the event name, dates, location, audience demographics, expected attendance, past sponsors, speaker lineup, and brand positioning. Then build me a professional sponsorship deck as a complete, designed document. The deck should include: 1) A compelling cover slide with event branding. 2) An event overview with mission, history, and key stats. 3) Audience demographics and psychographics — who attends, their job titles, industries, and buying power. 4) Reach and engagement metrics — social following, email list size, website traffic, past event attendance. 5) Three to four tiered sponsorship packages (e.g., Platinum, Gold, Silver, Bronze) with clear pricing, benefits, and deliverables for each tier — including logo placement, booth space, speaking slots, digital exposure, and lead capture opportunities. 6) Add-on sponsorship opportunities like lanyards, Wi-Fi, after-parties, and branded experiences. 7) A competitor landscape section showing who has sponsored similar events. 8) Social proof — testimonials or logos from past sponsors if available. 9) A clear call-to-action with contact information. Make the deck visually polished, data-driven, and ready to send to prospective sponsors.`,heroOverlaySteps:[`Researching your event, audience, and past sponsors`,`Building tiered sponsorship packages with pricing and benefits`,`Designing a polished, data-driven sponsorship deck`,`Your sponsorship deck complete — ready to send to prospects`],generatingSteps:[`Visiting {url} to extract event details, audience data, and sponsor history`,`Designing an agent to build tiered sponsorship packages with pricing and deliverables`,`Configuring audience demographics, reach metrics, and competitive sponsor analysis`,`Setting up your polished sponsorship deck with add-ons and social proof`],featureSectionTitle:`From event page to sponsor-ready deck`,featureCardTitles:[`Connects to your events stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Slides, Google Sheets, Canva, Notion, Google Drive — Computer builds your deck and pipes sponsorship data into the tools you already use.`,`Tiered sponsorship packages. Audience demographic breakdowns. Reach and engagement metrics. Add-on opportunities. A polished deck ready for prospective sponsors.`],capabilitySectionTitle:`Your partnerships team, on autopilot`,capabilitySectionSubtitle:`Paste your event URL, step away, come back to a sponsor-ready deck.`,capabilityCards:[{title:`Event Intelligence`,description:`Computer can research your event — attendance history, speaker lineup, audience demographics, and brand positioning — to build a compelling narrative for sponsors.`},{title:`Package Design`,description:`Computer can create tiered sponsorship packages with clear pricing, deliverables, and ROI projections — structured to maximize revenue per sponsor.`},{title:`Audience Profiling`,description:`Computer can compile audience demographics, psychographics, and engagement metrics — giving sponsors the data they need to say yes.`},{title:`Connect Your Tools`,description:`Computer can integrate with Google Sheets, Google Drive, Canva, Notion, and Slack — build workflows across your entire event management stack.`},{title:`Remember & Improve`,description:`Computer can remember your past events, sponsor feedback, and package performance — so every new deck is sharper than the last.`},{title:`Monitor & Alert`,description:`Computer can track competitor events for new sponsor signings and flag opportunities to adjust your packages or outreach timing.`}]});export{t as default};
